written = 0
for cid in EXPECTED:
    e = P[cid]
    rec = {"case_id": cid, "prediction_text": e["prediction_text"], "basis": e["basis"],
           "confidence": e["confidence"], "trigger": e["trigger"]}
    assert 0.0 <= rec["confidence"] <= 1.0
    for k in ("changed_main", "reserve_used", "disputed"):
        assert isinstance(rec["trigger"][k], bool)
    assert isinstance(rec["trigger"]["reason"], str)
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    written += 1

assert written == 40
c = sum(1 for cid in EXPECTED if P[cid]["trigger"]["changed_main"])
r = sum(1 for cid in EXPECTED if P[cid]["trigger"]["reserve_used"])
d = sum(1 for cid in EXPECTED if P[cid]["trigger"]["disputed"])
print(f"cases={len(EXPECTED)} written={written} changed_main={c} reserve_used={r} disputed={d}")
for cid in EXPECTED:
    with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
        json.load(f)
